// Prepare platform-specific messages with character limits & formatting
const item = $input.first().json.body || $input.first().json;

const caseId = item.case_id || 'UNKNOWN';
const childName = item.child_name || 'Missing Child';
const age = item.age ? `${item.age} years old` : '';
const location = item.location || item.last_seen_location || 'Unknown Location';
const caseUrl = item.case_url || `https://kidnap-children.org/posts/${caseId}`;
const imageUrl = item.image_url || 'https://kidnap-children.org/images/default_missing.png';
const contactPhone = item.contact_phone || 'Local Police / Hotline';
const hashtags = item.hashtags || '#MissingChild #UrgentAlert #HelpFindChild #KidnapChildren';

// 1. Twitter / X (Max 280 chars)
const twitterText = `🚨 URGENT MISSING CHILD 🚨\nName: ${childName} (${age})\nLast Seen: ${location}\nIf seen call: ${contactPhone}\nDetails: ${caseUrl}\n${hashtags}`.substring(0, 280);

// 2. Telegram (Markdown)
const telegramMessage = `🚨 *URGENT MISSING CHILD ALERT* 🚨\n\n*Name:* ${childName}\n*Age:* ${age}\n*Last Seen Location:* ${location}\n*Emergency Contact:* ${contactPhone}\n\nPlease share this immediately to help reunite this child with their family.\n\n🔗 [View Full Case Details & Submit Sighting](${caseUrl})`;

// 3. Facebook / Meta Graph API
const facebookMessage = `🚨 URGENT MISSING CHILD ALERT 🚨\nName: ${childName} (${age})\nLast Seen Location: ${location}\nContact Hotline: ${contactPhone}\n\nEvery second counts. Please share this post to reach more people in the area!\nFull case info: ${caseUrl}\n\n${hashtags}`;

// 4. Discord Emergency Channel (Rich Embed)
const discordEmbed = {
  embeds: [
    {
      title: `🚨 URGENT MISSING CHILD: ${childName.toUpperCase()}`,
      description: `Urgent case broadcast for **${childName}** (${age}). Please review the details below and share immediately.`,
      url: caseUrl,
      color: 15158332,
      fields: [
        { name: "Last Seen Location", value: location, inline: true },
        { name: "Emergency Hotline", value: contactPhone, inline: true },
        { name: "Case Reference", value: `#${caseId}`, inline: true }
      ],
      image: { url: imageUrl },
      footer: { text: "Kidnap-Children Social Broadcast Engine • Emergency Alert System" },
      timestamp: new Date().toISOString()
    }
  ]
};

return [{
  json: {
    case_id: caseId,
    image_url: imageUrl,
    case_url: caseUrl,
    formatted: {
      twitter: twitterText,
      telegram: telegramMessage,
      facebook: facebookMessage,
      discord: discordEmbed
    }
  }
}];

const item = $("Format Multi-Platform Posts").first().json;

return [{
  json: {
    status: "success",
    action: "social_broadcast_completed",
    case_id: item.case_id,
    published_platforms: [
      "Telegram Channel",
      "Discord Emergency Channel",
      "Facebook Page"
    ],
    broadcast_time: new Date().toISOString()
  }
}];
